function X({registerIndicator:g,sourceValues:h,nulls:k}){g({id:"oa-linreg",name:"Linear Regression (LINREG)",category:"Statistics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:2,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"linreg",type:"line",title:"LinReg",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,f){const t=Math.max(2,Math.floor(Number(f.period)||14)),L=h(s,f.source??"close"),m=new Array(s.length).fill(NaN),p=new Array(t).fill(0);let i=0,o=0,c=NaN;for(let l=0;l<s.length;l++){let n=L[l];!Number.isFinite(n)&&Number.isFinite(c)&&(n=c),Number.isFinite(n)&&(c=n,p[o]=n,i<t&&(i+=1),o=(o+1)%t);const e=i;if(e<2)continue;const x=i<t?0:o;let a=0,d=0;for(let r=0;r<e;r++){const b=p[(x+r)%t];a+=b,d+=r*b}const u=.5*(e-1)*e,F=(e-1)*e*(2*e-1)/6,y=e*F-u*u;if(y===0)continue;const N=(e*d-u*a)/y,R=a/e-N*((e-1)/2);m[l]=R+N*(e-1)}return{linreg:k(m)}}})}export{X as default};
